CREATE OR REPLACE FUNCTION public.admin_launch_readiness()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare v_checks jsonb;v_all_green boolean;v_users bigint;v_campaigns bigint;v_notifications bigint;v_properties bigint;v_verifications bigint;v_flags bigint;v_events bigint;v_warnings jsonb;
begin
 if private.current_user_profile_role()<>'admin' then raise exception 'administrator access required' using errcode='42501';end if;
 v_checks:=jsonb_build_array(
 jsonb_build_object('key','core_tables','label','Core tables exist','ok',to_regclass('public.profiles') is not null and to_regclass('public.campaigns') is not null and to_regclass('public.submissions') is not null and to_regclass('public.campaign_payments') is not null,'detail','Profiles, campaigns, submissions and payment records'),
 jsonb_build_object('key','publisher_tables','label','Publisher inventory and event tables exist','ok',to_regclass('public.publisher_properties') is not null and to_regclass('public.publisher_campaigns') is not null and to_regclass('public.ad_placement_events') is not null,'detail','Publisher properties, applications and event records'),
 jsonb_build_object('key','verification_notifications_tables','label','Verification and notifications tables exist','ok',to_regclass('public.creator_verification_submissions') is not null and to_regclass('public.notifications') is not null,'detail','Creator promo-post review and in-app inbox'),
 jsonb_build_object('key','fraud_assessments','label','Unified fraud assessment table exists','ok',to_regclass('public.adbridge_event_assessments') is not null and to_regclass('public.fraud_flags') is not null,'detail','Assessment evidence and investigation flags'),
 jsonb_build_object('key','rls','label','Sensitive tables have row-level security','ok',(select relrowsecurity from pg_class where oid=to_regclass('public.notifications')) and (select relrowsecurity from pg_class where oid=to_regclass('public.creator_verification_submissions')) and (select relrowsecurity from pg_class where oid=to_regclass('public.creator_platform_connections')) and (select relrowsecurity from pg_class where oid=to_regclass('public.adbridge_event_assessments')),'detail','Notifications, creator verification, social tokens and event assessments'),
 jsonb_build_object('key','fraud_triggers','label','Fraud assessment triggers installed','ok',(select count(*)>=4 from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and not t.tgisinternal and t.tgname in ('tracking_click_event_fraud_assessment','ad_placement_event_fraud_assessment','submission_metric_fraud_assessment','cpa_conversion_fraud_assessment')),'detail','Click, publisher, platform metric and conversion sources'),
 jsonb_build_object('key','payout_gates','label','Verified payout gates exist','ok',to_regprocedure('public.record_tracking_click(text,text,text,text,text)') is not null and to_regprocedure('public.release_cpm_submission_payment(uuid)') is not null and to_regprocedure('public.record_cpa_conversion(uuid,text,text,text,numeric)') is not null,'detail','CPC, CPM and CPA/CPI payout routines'),
 jsonb_build_object('key','measurement_rpcs','label','Verified measurement RPCs exist','ok',to_regprocedure('public.get_campaign_measurement_summary(uuid)') is not null and to_regprocedure('public.get_advertiser_measurement_summary()') is not null and to_regprocedure('public.get_creator_measurement_summary()') is not null,'detail','Advertiser and creator verified reports'),
 jsonb_build_object('key','rankings','label','Global rankings function exists','ok',to_regprocedure('public.get_adbridge_global_rankings()') is not null,'detail','Worldwide top 20 creator/publisher and advertiser ranking'),
 jsonb_build_object('key','creator_verification','label','Creator verification review RPC exists','ok',to_regprocedure('public.admin_review_creator_verification(uuid,text,text)') is not null,'detail','Transactional approval, profile badge and notification'),
 jsonb_build_object('key','notifications_triggers','label','Notification event triggers installed','ok',(select count(*)>=6 from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and not t.tgisinternal and t.tgname in ('publisher_application_notify_status','creator_submission_notify_status','advertiser_campaign_notify_status','advertiser_funding_notify_status','creator_cpm_payment_notify','creator_withdrawal_notify_status')),'detail','Publisher, submission, campaign, funding, CPM payout and withdrawal'),
 jsonb_build_object('key','realtime','label','Notifications are in Supabase Realtime publication','ok',exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='notifications'),'detail','Unread bell and inbox refresh'),
 jsonb_build_object('key','financial_reconciliation','label','Admin financial reconciliation RPC exists','ok',to_regprocedure('public.admin_financial_reconciliation()') is not null,'detail','Campaign funding, refunds, committed payouts and withdrawal reserve checks'),
 jsonb_build_object('key','publisher_earnings','label','Publisher earnings and withdrawal RPCs exist','ok',to_regprocedure('public.get_creator_earnings_summary()') is not null and to_regprocedure('public.request_creator_withdrawal(numeric)') is not null,'detail','Shared creator and publisher earnings balance and withdrawal requests'),
 jsonb_build_object('key','social_disconnect','label','Secure social disconnect RPC exists','ok',to_regprocedure('public.disconnect_creator_platform(text)') is not null,'detail','Disconnect clears locally stored OAuth tokens')
 );
 select bool_and((x->>'ok')::boolean) into v_all_green from jsonb_array_elements(v_checks) x;
 select count(*) into v_users from public.profiles;select count(*) into v_campaigns from public.campaigns;select count(*) into v_notifications from public.notifications;select count(*) into v_properties from public.publisher_properties;select count(*) into v_verifications from public.creator_verification_submissions;select count(*) into v_flags from public.fraud_flags where status in ('open','reviewing');select count(*) into v_events from public.adbridge_event_assessments;
 v_warnings:=jsonb_build_array();
 if v_users=0 then v_warnings:=v_warnings||jsonb_build_array('No user profiles yet. Signed-in end-to-end tests are not possible.');end if;
 if v_campaigns=0 then v_warnings:=v_warnings||jsonb_build_array('No campaigns yet. Advertiser funding, creator applications and payout flows need real test data.');end if;
 v_warnings:=v_warnings||jsonb_build_array('Paystack live credentials, OAuth provider credentials, and production webhook secrets must be verified in deployment settings. This readiness RPC does not inspect or reveal secrets.');
 return jsonb_build_object('all_green',coalesce(v_all_green,false),'data_ready',v_users>0 and v_campaigns>0,'checks',v_checks,'warnings',v_warnings,'counts',jsonb_build_object('profiles',v_users,'campaigns',v_campaigns,'notifications',v_notifications,'publisher_properties',v_properties,'verification_submissions',v_verifications,'open_fraud_flags',v_flags,'event_assessments',v_events),'checked_at',now());
end;$function$
